import{_ as i,o as r,c as d,a2 as s,j as t,a as o,t as a}from"./chunks/framework.C6DVv5ZP.js";const g=JSON.parse('{"title":"Keeping the screen mockups as a versioned source of truth","description":"","frontmatter":{},"headers":[],"relativePath":"docs/research/mockups-source-of-truth.md","filePath":"docs/research/mockups-source-of-truth.md"}'),l={name:"docs/research/mockups-source-of-truth.md"};function c(n,e,h,p,u,m){return r(),d("div",null,[e[45]||(e[45]=s('<h1 id="keeping-the-screen-mockups-as-a-versioned-source-of-truth" tabindex="-1">Keeping the screen mockups as a versioned source of truth <a class="header-anchor" href="#keeping-the-screen-mockups-as-a-versioned-source-of-truth" aria-label="Permalink to &quot;Keeping the screen mockups as a versioned source of truth&quot;">​</a></h1><p>Research notes, 25 October 2026. The owner chose the recommendation on 26 October 2026, with two changes (see &quot;Owner&#39;s answers&quot;); the decision is <a href="./../adr/0016-mockups-are-plain-html-in-the-repo">ADR 0016</a>.</p><h2 id="short-answer" tabindex="-1">Short answer <a class="header-anchor" href="#short-answer" aria-label="Permalink to &quot;Short answer&quot;">​</a></h2><p>Move the mockups into the repo as plain, standalone HTML pages (option 3), one file per screen under <code>design/mockups/</code>, styled only with the generated <code>--cp-*</code> CSS variables and the generated Poulpy SVGs, and show them on the docs site the way the brand book is shown today. Every change then goes through a PR, the history is Git&#39;s, Claude edits them like any other file, and a <code>--check</code> script in CI keeps them on the tokens, as ADR 0012 already does for themes and drawings. Do not commit the claude.ai canvas files as they are (option 2): they only render with the artifact type&#39;s runtime and their images only resolve on claude.ai. Once a screen ships, its truth moves to screenshot tests on each platform (option 5), added screen by screen later, and its mockup is marked shipped. The claude.ai canvas becomes a scratch space and comment preview, never the source.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2>',5)),t("ul",null,[e[16]||(e[16]=t("li",null,[o("Coach Poulpy is a Kotlin Multiplatform core with native Compose and SwiftUI apps, a Vue web placeholder and a VitePress docs site in "),t("code",null,"site/"),o(", built on every PR and published from "),t("code",null,"main"),o(" by "),t("code",null,".github/workflows/pages.yml"),o(". One developer works mostly through Claude agents.")],-1)),e[17]||(e[17]=t("li",null,[t("code",null,"docs/design-system.md"),o(' ("Screens") says the mockups canvas in the Claude project holds every screen, and that a new screen gets a mockup before it is built.')],-1)),t("li",null,[e[0]||(e[0]=o("That canvas is a claude.ai Design artifact: ",-1)),e[1]||(e[1]=t("code",null,"project/canvas.json",-1)),e[2]||(e[2]=o(" plus 42 ",-1)),e[3]||(e[3]=t("code",null,"project/*.dc.html",-1)),e[4]||(e[4]=o(" artboards at 390 by 844. The artboards use ",-1)),e[5]||(e[5]=t("code",null,"<x-dc>",-1)),e[6]||(e[6]=o(" markup with ",-1)),t("code",null,a(n.holes),1),e[7]||(e[7]=o(", ",-1)),e[8]||(e[8]=t("code",null,"<dc-import>",-1)),e[9]||(e[9]=o(" between artboards, a runtime supplied by the artifact type (",-1)),e[10]||(e[10]=t("code",null,"dc-runtime.js",-1)),e[11]||(e[11]=o(", ",-1)),e[12]||(e[12]=t("code",null,"app.js",-1)),e[13]||(e[13]=o(" of about 4.4 MB) and images or fonts stored as ",-1)),e[14]||(e[14]=t("code",null,"/_blob/<id>",-1)),e[15]||(e[15]=o(" URLs that only resolve on claude.ai. These facts were read from the artifact's file listing and its type instructions on 25 October 2026.",-1))]),e[18]||(e[18]=s("<li>Precedents in the repo: <code>design/tokens.json</code> and <code>design/build-poulpy.mjs</code> are single sources generated into every platform, with <code>--check</code> in CI (<code>docs/adr/0012-design-tokens-generated-from-one-file.md</code>, <code>design/README.md</code>). The brand book is one standalone HTML file, <code>site/public/brand/book.html</code> (about 61 KB, its only external dependency is Google Fonts), embedded in an iframe by <code>site/brand-book.md</code>.</li><li>The apps have no Compose Previews, SwiftUI Previews or screenshot tests yet (a search of the repo found none). The Android build uses AGP 8.13 and Kotlin 2.4 (<code>gradle/libs.versions.toml</code>).</li>",2))]),e[46]||(e[46]=s('<h3 id="mockups-and-shipped-screens-are-two-different-truths" tabindex="-1">Mockups and shipped screens are two different truths <a class="header-anchor" href="#mockups-and-shipped-screens-are-two-different-truths" aria-label="Permalink to &quot;Mockups and shipped screens are two different truths&quot;">​</a></h3><p>Write the Docs describes docs as code as &quot;writing documentation with the same tools as code&quot;: issue tracking, Git, plain-text markup, peer review and automated checks (<a href="https://writethedocs.org/guide/docs-as-code" target="_blank" rel="noreferrer">Write the Docs</a>). The UK Government Digital Service prototypes in HTML kept on GitHub because &quot;every change (&quot;commit&quot;) is tracked and can be rolled back&quot; and &quot;multiple people can contribute to a single prototype&quot;, while prototypes &quot;are made to be tested and iterated (and if they fail, thrown away)&quot; (<a href="https://designnotes.blog.gov.uk/2014/10/13/how-designers-prototype-at-gds/" target="_blank" rel="noreferrer">GDS design notes</a>); its prototype kit &quot;is designed for prototyping, not for production code&quot; (<a href="https://prototype-kit.service.gov.uk/docs/principles" target="_blank" rel="noreferrer">GOV.UK Prototype Kit principles</a>). The inference for this repo: a mockup is the intent before a screen exists and while it changes; once the screen ships, the app itself is the truth and the mockup should say so rather than silently drift.</p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>1. Canvas on claude.ai</th><th>2. Canvas files in repo</th><th>3. Plain HTML in repo</th><th>4. Figma or Penpot</th><th>5. Previews and screenshot tests</th><th>6. Committed images</th></tr></thead><tbody><tr><td>Single source</td><td>Canvas</td><td>Two copies to sync</td><td>Repo</td><td>Design tool</td><td>App code</td><td>Repo, but exported from elsewhere</td></tr><tr><td>PR review and diff</td><td>None</td><td>Text diff of DC markup</td><td>Text diff, plus rendered pages from CI</td><td>None in Git</td><td>Image diff of references</td><td>GitHub image diff</td></tr><tr><td>History</td><td>claude.ai versions</td><td>Git, plus claude.ai</td><td>Git</td><td>Tool (30 days on Figma Starter)</td><td>Git</td><td>Git</td></tr><tr><td>Claude can edit</td><td>Yes, through the artifact API</td><td>Yes, but must re-sync</td><td>Yes, any agent with the repo</td><td>Figma: beta, paid plans; Penpot: MCP</td><td>Yes, it writes the screen</td><td>Only by regenerating</td></tr><tr><td>Docs site</td><td>Link only</td><td>Does not render without the runtime</td><td>Iframe, like the brand book</td><td>Live embed (Figma)</td><td>Show the reference PNGs</td><td><code>&lt;img&gt;</code></td></tr><tr><td>Drift with real screens</td><td>Not detected</td><td>Not detected</td><td>Token check only</td><td>Code Connect links components, not screens</td><td>Caught in CI</td><td>Not detected</td></tr><tr><td>Cost and lock-in</td><td>Free, tied to claude.ai</td><td>Tied to claude.ai runtime</td><td>None</td><td>Figma plans; Penpot free, self-hostable</td><td>None</td><td>LFS quota if used</td></tr><tr><td>Setup effort</td><td>None</td><td>Medium, ongoing sync</td><td>One-time conversion of 42 artboards</td><td>High, redraw everything</td><td>Medium per platform, per screen</td><td>Low</td></tr></tbody></table><h2 id="option-1-keep-the-claude-ai-canvas-as-the-source" tabindex="-1">Option 1: keep the claude.ai canvas as the source <a class="header-anchor" href="#option-1-keep-the-claude-ai-canvas-as-the-source" aria-label="Permalink to &quot;Option 1: keep the claude.ai canvas as the source&quot;">​</a></h2><p>This is today. It is the cheapest and keeps comments and claude.ai version history. Its weaknesses are the ones raised in the project chat: no PR review, a change can land without anyone seeing it next to the code it affects, the history lives outside the repo, and the canvas is private, so the docs site can only link to it. Committing exported PNG snapshots next to it (option 6) adds a visible history in Git but creates a second copy that drifts the day someone forgets to export (inference). Keep this as the place for quick exploration, not as the record.</p><h2 id="option-2-commit-the-canvas-files-canvas-json-and-dc-html" tabindex="-1">Option 2: commit the canvas files (<code>canvas.json</code> and <code>.dc.html</code>) <a class="header-anchor" href="#option-2-commit-the-canvas-files-canvas-json-and-dc-html" aria-label="Permalink to &quot;Option 2: commit the canvas files (`canvas.json` and `.dc.html`)&quot;">​</a></h2><p>This gives a Git history and PRs, but the files are not the screens: they are templates for a runtime that the claude.ai artifact type supplies (<code>dc-runtime.js</code>, about 4.4 MB of <code>app.js</code>), and their images and fonts are <code>/_blob/&lt;id&gt;</code> URLs that only resolve on claude.ai (read from the artifact). So:</p>',8)),t("ul",null,[e[23]||(e[23]=t("li",null,"The docs site cannot render them unless the runtime is vendored into the repo, which is a proprietary bundle the project does not control and whose licence for redistribution is unknown (not verified).",-1)),t("li",null,[e[19]||(e[19]=o("A diff shows ",-1)),e[20]||(e[20]=t("code",null,"<x-dc>",-1)),e[21]||(e[21]=o(" markup and ",-1)),t("code",null,a(n.holes),1),e[22]||(e[22]=o(", readable but not what the screen looks like.",-1))]),e[24]||(e[24]=t("li",null,"Two-way sync means every edit on either side must be copied to the other, with no tool that detects when they diverge (inference). With one developer and several agents, the two copies will drift.",-1))]),e[47]||(e[47]=s('<p>Only worth it if the canvas editor stays the main editing tool, which conflicts with &quot;every change goes through a PR&quot;.</p><h2 id="option-3-plain-standalone-html-mockups-in-the-repo" tabindex="-1">Option 3: plain standalone HTML mockups in the repo <a class="header-anchor" href="#option-3-plain-standalone-html-mockups-in-the-repo" aria-label="Permalink to &quot;Option 3: plain standalone HTML mockups in the repo&quot;">​</a></h2><p>Each screen is a small HTML page, 390 by 844, like the brand book: no runtime, Google Fonts or the bundled fonts, <code>web/src/styles/tokens.css</code> for colours, type and spacing, and <code>design/poulpy/*.svg</code> for Poulpy. This is docs as code in the Write the Docs sense (<a href="https://writethedocs.org/guide/docs-as-code" target="_blank" rel="noreferrer">Write the Docs</a>) and the GDS way of prototyping in HTML under version control (<a href="https://designnotes.blog.gov.uk/2014/10/13/how-designers-prototype-at-gds/" target="_blank" rel="noreferrer">GDS design notes</a>).</p>',3)),t("ul",null,[e[34]||(e[34]=s('<li><strong>Source and edits.</strong> The repo holds the only copy. Claude agents edit it with ordinary file tools, in a branch, through a PR; the owner can still open a file in a browser and tweak it by hand.</li><li><strong>Review.</strong> GitHub shows an HTML change as a text diff, not as a picture (inference from how GitHub renders non-code files: its list of rendered formats names images, CSV, PDF, 3D and maps, not HTML; <a href="https://docs.github.com/en/repositories/working-with-files/using-files/working-with-non-code-files" target="_blank" rel="noreferrer">GitHub Docs</a>). To see the change, a CI job can render each changed mockup to PNG with Playwright and upload the images as a build artifact. Playwright warns that &quot;browser rendering can vary based on the host OS, version, settings, hardware&quot;, so pixel baselines only hold when made in the same environment (<a href="https://playwright.dev/docs/test-snapshots" target="_blank" rel="noreferrer">Playwright</a>); that is why this note suggests uploading renders for review rather than committing them as baselines.</li><li><strong>Docs site.</strong> The pages are static files, so the site can embed them in iframes the way <code>site/brand-book.md</code> embeds <code>book.html</code>, and the Pages build on every PR already fails if a page breaks.</li><li><strong>Drift.</strong> A script in the spirit of ADR 0012 can fail CI when a mockup uses a raw colour, a font size or a spacing value outside the tokens, links a missing Poulpy drawing, or is missing from the index. It cannot tell whether the shipped screen still matches; that is option 5&#39;s job.</li>',4)),t("li",null,[e[25]||(e[25]=t("strong",null,"Cost.",-1)),e[26]||(e[26]=o(" One conversion of the 42 artboards: inline each ",-1)),e[27]||(e[27]=t("code",null,"<dc-import>",-1)),e[28]||(e[28]=o(", fill the ",-1)),t("code",null,a(n.holes),1),e[29]||(e[29]=o(" with real sample text, download each ",-1)),e[30]||(e[30]=t("code",null,"/_blob/",-1)),e[31]||(e[31]=o(" image or replace it with a generated Poulpy SVG, and swap hard-coded values for ",-1)),e[32]||(e[32]=t("code",null,"var(--cp-*)",-1)),e[33]||(e[33]=o(". Claude can read the artifact's files to do this (inference: the Artifact tool can read an artifact's published files by path).",-1))]),e[35]||(e[35]=t("li",null,[t("strong",null,"Loss."),o(" Canvas comments and the canvas's free arrangement of artboards. An index page with sections and notes from "),t("code",null,"canvas.json"),o(" replaces the arrangement; PR comments replace canvas comments.")],-1))]),e[48]||(e[48]=s('<h2 id="option-4-figma-or-penpot" tabindex="-1">Option 4: Figma or Penpot <a class="header-anchor" href="#option-4-figma-or-penpot" aria-label="Permalink to &quot;Option 4: Figma or Penpot&quot;">​</a></h2><p>Figma is the industry default and has the richest tooling, but most of it sits behind paid plans:</p><ul><li>On the Starter plan users &quot;can only access up to 30 days of version history&quot; (<a href="https://help.figma.com/hc/en-us/articles/360038006754" target="_blank" rel="noreferrer">Figma Learn</a>). Branching is &quot;available on the Organization and Enterprise plans&quot; and needs a Full seat (<a href="https://help.figma.com/hc/en-us/articles/360063144053" target="_blank" rel="noreferrer">Figma Learn</a>).</li><li>Code Connect shows real code snippets in Dev Mode for React, HTML, SwiftUI and Jetpack Compose, and needs &quot;a Dev or Full seat on the Professional, Organization, or Enterprise plan&quot; (<a href="https://developers.figma.com/docs/code-connect/quickstart-guide" target="_blank" rel="noreferrer">Figma developer docs</a>). It links components, not whole screens, so it does not detect a screen drifting from its design.</li><li>Agents can now edit files through the remote MCP server&#39;s <code>use_figma</code> tool, but &quot;writing to the canvas is currently in beta&quot;, on Professional plans and up, and will become paid by usage (<a href="https://developers.figma.com/docs/figma-mcp-server/write-to-canvas" target="_blank" rel="noreferrer">Figma developer docs</a>).</li><li>&quot;Figma Live Embeds allow you to add live Figma files or prototypes into other websites or apps&quot; (<a href="https://help.figma.com/hc/en-us/articles/360039827514" target="_blank" rel="noreferrer">Figma Learn</a>), so the docs site could embed frames.</li></ul><p>Penpot is open source (MPL 2.0), &quot;designed for self-hosting&quot;, &quot;works with open standards like SVG, CSS, HTML, and JSON&quot;, and offers an MCP server and an open API (<a href="https://github.com/penpot/penpot" target="_blank" rel="noreferrer">Penpot on GitHub</a>). Its README did not describe file version history, so that is unverified here.</p><p>Either way the source moves out of Git into a tool with its own history, no PR review and a full redraw of every screen. For one developer working through agents, this adds a tool without solving review or drift.</p><h2 id="option-5-code-as-the-mockup-with-screenshot-tests" tabindex="-1">Option 5: code as the mockup, with screenshot tests <a class="header-anchor" href="#option-5-code-as-the-mockup-with-screenshot-tests" aria-label="Permalink to &quot;Option 5: code as the mockup, with screenshot tests&quot;">​</a></h2><p>Here the truth is the shipped screen, rendered from Compose Previews and SwiftUI views, and the reference images committed next to the tests.</p><ul><li><strong>Android, Google&#39;s tool.</strong> Compose Preview Screenshot Testing renders <code>@PreviewTest</code> previews on the host, stores references in <code>{module}/src/screenshotTest{Variant}/reference</code>, and fails <code>validateDebugScreenshotTest</code> with an HTML report on a difference. It is alpha (&quot;features and APIs are subject to change substantially&quot;), the standalone plugin is already deprecated in favour of AGP test suites from AGP 9.5, and the Gradle-only route needs AGP 8.5 or later (<a href="https://developer.android.com/studio/preview/compose-screenshot-testing" target="_blank" rel="noreferrer">Android Developers</a>). The repo&#39;s AGP 8.13 qualifies.</li><li><strong>Android, Roborazzi.</strong> Runs on the JVM with Robolectric, no emulator; <code>recordRoborazziDebug</code>, <code>compareRoborazziDebug</code> and <code>verifyRoborazziDebug</code> record, diff and fail; it can generate tests from <code>@Preview</code> functions with ComposablePreviewScanner. Its default output is <code>build/outputs/roborazzi</code>, so <code>outputDir</code> must point into <code>src/</code> for references to be committed (<a href="https://github.com/takahirom/roborazzi" target="_blank" rel="noreferrer">Roborazzi</a>).</li><li><strong>iOS.</strong> swift-snapshot-testing records a reference on the first run (the test fails once) into <code>__Snapshots__</code> next to the test, and warns that &quot;snapshots must be compared using the exact same simulator that originally took the reference&quot; (<a href="https://swiftpackageregistry.com/pointfreeco/swift-snapshot-testing" target="_blank" rel="noreferrer">swift-snapshot-testing</a>). CI&#39;s iOS job would need a pinned simulator.</li><li><strong>Web.</strong> Storybook &quot;supports cross-browser visual testing natively using Chromatic, a cloud service&quot; (<a href="https://storybook.js.org/docs/writing-tests/visual-testing" target="_blank" rel="noreferrer">Storybook</a>); not needed while the web app is a placeholder.</li></ul><p>Committed PNG references get GitHub&#39;s image diff in PRs, with 2-up, swipe and onion skin views, the last of which &quot;really comes in handy when elements move around by small, hard to notice amounts&quot; (<a href="https://docs.github.com/en/repositories/working-with-files/using-files/working-with-non-code-files" target="_blank" rel="noreferrer">GitHub Docs</a>). This is the only option that catches a real screen drifting. It cannot hold a screen that does not exist yet, so it complements a mockup rather than replacing it.</p><h2 id="option-6-exported-images-committed-to-the-repo" tabindex="-1">Option 6: exported images committed to the repo <a class="header-anchor" href="#option-6-exported-images-committed-to-the-repo" aria-label="Permalink to &quot;Option 6: exported images committed to the repo&quot;">​</a></h2><p>GitHub renders PNG, JPG, GIF and SVG and diffs images in three views (<a href="https://docs.github.com/en/repositories/working-with-files/using-files/working-with-non-code-files" target="_blank" rel="noreferrer">GitHub Docs</a>), so committed exports review well. But an image is an output: whoever edits must export again, and nothing fails when they forget (inference). If the images grow large, Git LFS on GitHub Free includes 10 GiB of storage and 10 GiB of bandwidth (<a href="https://docs.github.com/en/billing/concepts/product-billing/git-lfs" target="_blank" rel="noreferrer">GitHub Docs</a>), and <code>actions/checkout</code> does not fetch LFS files unless <code>lfs: true</code> is set (<a href="https://github.com/actions/checkout" target="_blank" rel="noreferrer">actions/checkout</a>), so the Pages build would need that flag. At 42 phone screens the images are small enough that LFS is not needed (inference). Useful as a generated by-product of option 3, not as a source.</p><h2 id="recommendation-for-this-repo" tabindex="-1">Recommendation for this repo <a class="header-anchor" href="#recommendation-for-this-repo" aria-label="Permalink to &quot;Recommendation for this repo&quot;">​</a></h2><p>Option 3 for intent, option 5 for shipped screens, the canvas as scratch.</p>',13)),t("ol",null,[e[43]||(e[43]=s("<li><strong>Record the decision.</strong> Add ADR 0016, &quot;Mockups are plain HTML in the repo&quot;, and rewrite the &quot;Screens&quot; section of <code>docs/design-system.md</code>: mockups live in <code>design/mockups/</code>, a new screen gets a mockup in a PR before it is built, and the claude.ai canvas is only a scratch space. This changes the rule in <code>docs/design-system.md</code>; it does not contradict ADR 0012, it extends it.</li><li><strong>Folder layout.</strong> One file per artboard, such as <code>design/mockups/home-planned.html</code>, plus a shared <code>design/mockups/mockup.css</code> for the phone frame and common components (Primary button, Chip, Poulpy card, Plan sheet...). Each file says what it is in its own <code>&lt;head&gt;</code> (see &quot;How a mockup file is written&quot; below), and the site&#39;s gallery is built from those headers, so there is no separate index to keep in step. Mockups read <code>web/src/styles/tokens.css</code> and <code>design/poulpy/*.svg</code>; no copied hex values.</li>",2)),t("li",null,[e[36]||(e[36]=t("strong",null,"Convert once.",-1)),e[37]||(e[37]=o(" A Claude session reads the canvas artboards from the artifact, inlines each ",-1)),e[38]||(e[38]=t("code",null,"<dc-import>",-1)),e[39]||(e[39]=o(", fills each ",-1)),t("code",null,a(n.hole),1),e[40]||(e[40]=o(" with sample content in glossary terms (a Workout, a Session, a Plan), replaces ",-1)),e[41]||(e[41]=t("code",null,"/_blob/",-1)),e[42]||(e[42]=o(" images with generated Poulpy drawings or committed files, and opens one PR per section so each stays reviewable. Keep the canvas link in the ADR as the archive of the old version.",-1))]),e[44]||(e[44]=s("<li><strong>Show them on the site.</strong> Extend <code>site/copy-docs.mjs</code> to copy <code>design/mockups/</code> and the token CSS and Poulpy SVGs they use into <code>site/public/mockups/</code>, and add <code>site/mockups.md</code>, a gallery of 390 by 844 iframes grouped by section with each status, linked from the Design system sidebar. The site then always shows <code>main</code>.</li><li><strong>Check in CI.</strong> Add <code>design/check-mockups.mjs</code>, run in the website job of <code>ci.yml</code> next to the two existing <code>--check</code> steps. It fails when a mockup&#39;s header is missing or incomplete, uses a colour, font size, radius or spacing value that is not a <code>var(--cp-*)</code>, references a missing Poulpy SVG or image, loads a script from anywhere but the repo, or calls the network (<code>fetch</code>, <code>XMLHttpRequest</code>). Optionally, a second job renders each changed mockup to PNG with Playwright and uploads them as a build artifact for review.</li><li><strong>How Claude edits.</strong> Like any change: an issue, a <code>design/&lt;issue&gt;-&lt;short-description&gt;</code> branch, edits to the HTML, the check, a PR. To get comments on a draft, Claude may publish the file as a private artifact, but the PR is the record and nothing is copied back from claude.ai by hand.</li><li><strong>After a screen ships.</strong> Add screenshot tests for it on both platforms in the same PR or the next one: Roborazzi (stable, previews-based, references under <code>app-android/src/test/screenshots</code>) or Google&#39;s Compose Preview Screenshot Testing once AGP test suites settle, and swift-snapshot-testing on a pinned simulator. Mark the mockup <code>shipped</code> and link its references; from then on a change to that screen updates the code and its references, and the mockup only changes when the screen is redesigned.</li>",4))]),e[49]||(e[49]=s('<h3 id="how-a-mockup-file-is-written" tabindex="-1">How a mockup file is written <a class="header-anchor" href="#how-a-mockup-file-is-written" aria-label="Permalink to &quot;How a mockup file is written&quot;">​</a></h3><p>The owner&#39;s PR comment listed practices for static HTML mockups. Checked against this repo, most of them fit, with some changes.</p><ul><li><strong>A phone frame.</strong> Every screen sits in the same 390 by 844 frame from <code>mockup.css</code>, with rounded corners. Agreed. The iframe already keeps a mockup&#39;s CSS from leaking into the docs site, so the frame is for looks and a constant size, not isolation. No browser-window frame until the website has real screens.</li><li><strong>A header in the file.</strong> Agreed, and it means no separate index file. Each file opens with machine-readable tags that the check script and the gallery read: <code>&lt;title&gt;</code>, then <code>&lt;meta name=&quot;mockup:screen&quot; content=&quot;home-planned&quot;&gt;</code>, <code>mockup:section</code> (Home, Library...), <code>mockup:status</code> (<code>draft</code>, <code>agreed</code> or <code>shipped</code>), <code>mockup:issue</code> and, once shipped, <code>mockup:references</code> (the screenshot test files). Meta tags rather than an HTML comment, because a script can read them reliably and a malformed comment would pass silently (inference).</li><li><strong>Names agents can find.</strong> Agreed in spirit, lighter in form. The suggested <code>data-agent-id</code>, <code>data-agent-action</code> and <code>data-agent-state</code> attributes are not a standard (no primary source found), and an action or state written next to the markup can drift from what the markup shows. Instead: real elements (<code>&lt;button&gt;</code>, <code>&lt;a&gt;</code>, labels), which <code>docs/design-system.md</code> already requires for accessibility; one <code>data-component</code> attribute naming the design-system component (<code>primary-button</code>, <code>chip</code>, <code>poulpy-card</code>), which the check script can verify; and an <code>id</code> on each region an issue would name, in glossary terms from <code>CONTEXT.md</code> (<code>plan-sheet</code>, <code>session-summary</code>). A grep for those finds the element as easily as for a <code>data-agent-id</code>.</li><li><strong>No network.</strong> Agreed, and enforced by the check (step 5). Sample content is literal text in the markup, in glossary terms. Interaction, such as opening a sheet or switching a tab, uses a few lines of inline script or a separate file per state (<code>library-actions.html</code>), as the canvas does today; no framework.</li><li><strong>Rules in <code>CLAUDE.md</code>.</strong> Agreed: when the decision is made, <code>CLAUDE.md</code> gains one line under &quot;House rules&quot; pointing to <code>design/mockups/</code> and the check command, and <code>docs/design-system.md</code> holds the full rules, as it already does for tokens. The comment&#39;s claim that this saves tokens through caching is not something this note verified.</li></ul><h2 id="owner-s-answers" tabindex="-1">Owner&#39;s answers <a class="header-anchor" href="#owner-s-answers" aria-label="Permalink to &quot;Owner&#39;s answers&quot;">​</a></h2><p>The owner took the suggested answer to each open question, on 26 October 2026:</p><ul><li>Mockups become plain HTML in the repo; the canvas stays a scratch space, and losing its comments and free placement is acceptable.</li><li>They live in <code>design/mockups/</code>, not <code>site/public/mockups/</code>.</li><li>English only, light only.</li><li>Rendered PNGs are uploaded by CI, not committed.</li><li>Roborazzi on Android; a pinned iOS simulator in CI is acceptable for swift-snapshot-testing.</li><li>A shipped mockup is kept, frozen, and marked shipped.</li></ul><p>Two changes to the plan above:</p><ul><li><strong>Drafts are isolated from validated mockups</strong>: <code>drafts/</code> and <code>agreed/</code> folders instead of a status tag, and validating a draft is a PR that moves it to <code>agreed/</code>.</li><li><strong>Tablet and website screens are coming</strong>, so each of those folders is split into <code>phone/</code>, <code>tablet/</code> and <code>web/</code>, each with its own device frame, and a screen keeps the same file name across them.</li></ul><p>ADR 0016 records the resulting layout and rules.</p><h2 id="not-verified" tabindex="-1">Not verified <a class="header-anchor" href="#not-verified" aria-label="Permalink to &quot;Not verified&quot;">​</a></h2><ul><li>Whether the claude.ai artifact runtime may be redistributed in a public repo.</li><li>Penpot&#39;s file version history.</li><li>That GitHub shows HTML files only as source in PR diffs is inferred, not read in GitHub&#39;s docs.</li></ul>',11))])}const b=i(l,[["render",c]]);export{g as __pageData,b as default};
